insert into public.questions (exam_category, subject, topic, type, difficulty, body, body_hi, question_data, options, marks_correct, marks_wrong, explanation, explanation_hi, concept_group_id, source_type, source_citation, status)
values
('upsc','Environment & Ecology','Climate Science & Mitigation','mcq','easy','At higher levels of the atmosphere, ozone is formed when','वायुमंडल के ऊँचे स्तरों पर ओज़ोन तब बनती है जब','{"craft": "precision"}'::jsonb,'[{"id": "a", "body": "lightning in thunderclouds makes nitrogen and oxygen combine into a new gas", "body_hi": "गरजते बादलों में बिजली नाइट्रोजन और ऑक्सीजन को मिलाकर एक नई गैस बनाती है", "isCorrect": false}, {"id": "b", "body": "chlorofluorocarbons released at the surface react with water vapour high in the clouds", "body_hi": "सतह पर छोड़े गए क्लोरोफ़्लोरोकार्बन बादलों में ऊपर जलवाष्प से अभिक्रिया करते हैं", "isCorrect": false}, {"id": "c", "body": "carbon dioxide breaks down in strong sunlight", "body_hi": "तेज़ धूप में कार्बन डाइऑक्साइड टूट जाती है", "isCorrect": false}, {"id": "d", "body": "UV radiation splits oxygen molecules, and the freed atoms join other oxygen molecules", "body_hi": "पराबैंगनी विकिरण ऑक्सीजन अणुओं को तोड़ता है, और मुक्त परमाणु अन्य ऑक्सीजन अणुओं से जुड़ जाते हैं", "isCorrect": true}]'::jsonb,2,0.66,'High-energy ultraviolet radiation splits some oxygen (O2) molecules into free oxygen atoms, which then combine with other O2 molecules to form ozone (O3). Ozone at that level shields the surface from the Sun''s harmful ultraviolet radiation; CFCs do not make ozone but destroy it, releasing chlorine that breaks ozone molecules apart.','उच्च ऊर्जा वाला पराबैंगनी विकिरण कुछ ऑक्सीजन (O2) अणुओं को मुक्त ऑक्सीजन परमाणुओं में तोड़ता है, जो फिर अन्य O2 अणुओं से जुड़कर ओज़ोन (O3) बनाते हैं। उस स्तर पर ओज़ोन पृथ्वी की सतह को सूर्य के हानिकारक पराबैंगनी विकिरण से बचाती है; CFC ओज़ोन नहीं बनाते, बल्कि उसे नष्ट करते हैं -- वे क्लोरीन छोड़ते हैं, जो ओज़ोन अणुओं को तोड़ देती है।','l1-env-ozone-formation-uv','original_pattern_matched','NCERT Class X, Science (Our Environment).','draft'),
('upsc','Environment & Ecology','Climate Science & Mitigation','statement_based','easy','Consider the following statements about the ozone layer:','ओज़ोन परत के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The thinning of the ozone layer from the 1980s was linked to synthetic chemicals such as CFCs, used as refrigerants and in fire extinguishers.", "In 1987 the United Nations Environment Programme forged an agreement to freeze the production of CFCs at 1986 levels."], "statements_hi": ["1980 के दशक से ओज़ोन परत के पतले होने को CFC जैसे कृत्रिम रसायनों से जोड़ा गया, जो प्रशीतक (refrigerant) के रूप में और अग्निशामकों में प्रयुक्त होते थे।", "1987 में संयुक्त राष्ट्र पर्यावरण कार्यक्रम ने CFC के उत्पादन को 1986 के स्तर पर रोक देने का समझौता करवाया।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct. The amount of ozone in the atmosphere began to drop sharply in the 1980s, and the decrease was linked to CFCs; the 1987 agreement, the Montreal Protocol, began the international effort to control them, and it is now mandatory for manufacturers to make CFC-free refrigerators. The episode shows how an environmental problem can be solved only by countries acting together, since ozone-depleting gases released anywhere affect the whole planet.','दोनों कथन सही हैं। वायुमंडल में ओज़ोन की मात्रा 1980 के दशक में तेज़ी से घटने लगी, और इस कमी को CFC से जोड़ा गया; 1987 के समझौते, मॉन्ट्रियल प्रोटोकॉल, ने उन्हें नियंत्रित करने का अंतरराष्ट्रीय प्रयास शुरू किया, और अब निर्माताओं के लिए CFC-मुक्त रेफ़्रिजरेटर बनाना अनिवार्य है। यह प्रसंग दिखाता है कि कुछ पर्यावरणीय समस्याएँ देशों के मिलकर काम करने से ही सुलझ सकती हैं, क्योंकि कहीं भी छोड़ी गई ओज़ोन-क्षयकारी गैसें पूरे ग्रह को प्रभावित करती हैं।','l1-env-cfc-thinning-1987-freeze','original_pattern_matched','NCERT Class X, Science (Our Environment).','draft'),
('upsc','Environment & Ecology','Climate Science & Mitigation','statement_based','easy','Consider the following statements about the greenhouse effect:','ग्रीनहाउस प्रभाव के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Without the natural greenhouse effect, the average temperature at the Earth''s surface would be about -18 °C instead of about 15 °C.", "The greenhouse effect is caused entirely by human activities."], "statements_hi": ["प्राकृतिक ग्रीनहाउस प्रभाव के बिना पृथ्वी की सतह का औसत तापमान लगभग 15 °C के बजाय लगभग -18 °C होता।", "ग्रीनहाउस प्रभाव पूरी तरह मानवीय गतिविधियों के कारण होता है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "inference"}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: greenhouse gases in the atmosphere absorb part of the heat radiated by the Earth and send some of it back, keeping the planet habitable. Statement 2 is wrong: the greenhouse effect is a natural phenomenon; what humans have done, by burning fossil fuels and clearing forests, is to raise the concentration of greenhouse gases and so enhance it, which causes global warming.','केवल कथन 1 सही है: वायुमंडल की ग्रीनहाउस गैसें पृथ्वी से निकलने वाली ऊष्मा का एक भाग सोखकर उसका कुछ भाग वापस भेज देती हैं, जिससे ग्रह रहने योग्य बना रहता है। कथन 2 गलत है: ग्रीनहाउस प्रभाव एक प्राकृतिक घटना है; मनुष्यों ने जीवाश्म ईंधन जलाकर और वन काटकर ग्रीनहाउस गैसों की सांद्रता बढ़ाई है और इस तरह इस प्रभाव को बढ़ाया है, जिससे वैश्विक तापन होता है।','l1-env-greenhouse-minus-18','original_pattern_matched','NCERT Class XII, Biology (Environmental Issues, earlier editions).','draft'),
('upsc','Environment & Ecology','Climate Science & Mitigation','statement_based','easy','Consider the following statements about a box-type solar cooker:','बॉक्स प्रकार के सौर कुकर के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Its inside is painted black, because a black surface absorbs more heat.", "Its glass cover lets sunlight in but traps the heat inside, as in a greenhouse.", "A mirror reflector is used to send more sunlight into the box."], "statements_hi": ["इसका भीतरी भाग काला रँगा जाता है, क्योंकि काली सतह अधिक ऊष्मा सोखती है।", "इसका काँच का ढक्कन धूप को भीतर आने देता है पर ऊष्मा को ग्रीनहाउस की तरह भीतर रोक लेता है।", "बक्से में अधिक धूप भेजने के लिए दर्पण-परावर्तक का उपयोग होता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "application"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. A solar cooker uses three ideas together -- absorption by a black surface, trapping of heat under glass, and concentration of sunlight by a mirror -- to reach temperatures of about 100-140 °C in a few hours. It needs no fuel and causes no pollution, but it works only when the Sun is shining and cooks slowly, which limits its use.','तीनों कथन सही हैं। सौर कुकर तीन विचारों का एक साथ उपयोग करता है -- काली सतह द्वारा अवशोषण, काँच के नीचे ऊष्मा का रुकना, और दर्पण से धूप का संकेंद्रण -- जिससे कुछ घंटों में लगभग 100-140 °C तापमान मिल जाता है। इसमें कोई ईंधन नहीं लगता और प्रदूषण नहीं होता, पर यह केवल धूप में काम करता है और धीरे पकाता है, जिससे इसका उपयोग सीमित है।','l1-env-solar-cooker-black-glass-mirror','original_pattern_matched','NCERT Class X, Science (Sources of Energy, earlier editions).','draft'),
('upsc','Environment & Ecology','Climate Science & Mitigation','assertion_reason','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "Planting trees helps to slow down global warming.", "assertion_hi": "वृक्ष लगाना वैश्विक तापन को धीमा करने में मदद करता है।", "reason": "Trees take up carbon dioxide from the air during photosynthesis and store the carbon in their wood.", "reason_hi": "वृक्ष प्रकाश-संश्लेषण के दौरान वायु से कार्बन डाइऑक्साइड लेते हैं और कार्बन को अपनी लकड़ी में संचित करते हैं।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true, "craft": "inference"}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": true}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct, and Statement-II explains Statement-I: growing forests act as carbon sinks, drawing down carbon dioxide, the main greenhouse gas from human activity. The benefit lasts only as long as the carbon stays locked up -- if the trees burn or are cut and left to rot, the carbon returns to the air -- which is why protecting existing forests matters as much as planting new ones.','दोनों कथन सही हैं, और कथन-II कथन-I की व्याख्या करता है: बढ़ते वन कार्बन सिंक का काम करते हैं और मानवीय गतिविधियों से निकलने वाली मुख्य ग्रीनहाउस गैस, कार्बन डाइऑक्साइड, को सोखते हैं। यह लाभ तभी तक रहता है जब तक कार्बन बंद रहे -- यदि वृक्ष जल जाएँ या काटकर सड़ने छोड़ दिए जाएँ, तो कार्बन वायु में लौट आता है -- इसीलिए मौजूदा वनों की रक्षा उतनी ही महत्वपूर्ण है जितना नए वृक्ष लगाना।','l1-env-trees-carbon-sink-ar','original_pattern_matched','NCERT Class XII, Biology (Ecosystem; Environmental Issues).','draft'),
('upsc','Environment & Ecology','Climate Science & Mitigation','mcq','medium','According to the Petroleum Conservation Research Association, which one of the following helps a driver save fuel?','पेट्रोलियम संरक्षण अनुसंधान संघ (PCRA) के अनुसार निम्नलिखित में से कौन-सा उपाय चालक को ईंधन बचाने में मदद करता है?','{"craft": "application"}'::jsonb,'[{"id": "a", "body": "Keeping the engine running while waiting at traffic lights", "body_hi": "ट्रैफ़िक लाइट पर प्रतीक्षा करते समय इंजन चालू रखना", "isCorrect": false}, {"id": "b", "body": "Driving at a constant and moderate speed", "body_hi": "स्थिर और मध्यम गति से गाड़ी चलाना", "isCorrect": true}, {"id": "c", "body": "Keeping the tyres under-inflated for a softer ride", "body_hi": "आरामदायक सवारी के लिए टायरों में कम हवा रखना", "isCorrect": false}, {"id": "d", "body": "Accelerating and braking sharply in city traffic", "body_hi": "शहर के यातायात में अचानक गति बढ़ाना और ब्रेक लगाना", "isCorrect": false}]'::jsonb,2,0.66,'PCRA''s advice is to drive at a constant and moderate speed as far as possible, switch off the engine at traffic lights or wherever one has to wait, keep the tyres at the correct pressure, and maintain the vehicle regularly. Saving petrol and diesel matters both because they are exhaustible fossil fuels, formed over millions of years, and because burning them adds carbon dioxide and other pollutants to the air.','PCRA की सलाह है कि जहाँ तक हो सके स्थिर और मध्यम गति से गाड़ी चलाएँ, ट्रैफ़िक लाइट पर या जहाँ प्रतीक्षा करनी हो वहाँ इंजन बंद कर दें, टायरों में सही दबाव रखें, और वाहन का नियमित रखरखाव करें। पेट्रोल और डीज़ल बचाना इसलिए भी ज़रूरी है कि वे लाखों वर्षों में बने समाप्य जीवाश्म ईंधन हैं, और इसलिए भी कि उन्हें जलाने से वायु में कार्बन डाइऑक्साइड और अन्य प्रदूषक जुड़ते हैं।','l1-env-pcra-fuel-saving-driving','original_pattern_matched','NCERT Class VIII, Science (Coal and Petroleum).','draft'),
('upsc','Environment & Ecology','Climate Science & Mitigation','statement_based','medium','Consider the following statements about sources of energy:','ऊर्जा के स्रोतों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["A biogas plant produces a gas that is mostly methane, and the slurry left behind makes good manure.", "Ocean thermal energy can be tapped only where the surface water is about 20 °C or more warmer than the water deeper down.", "Geothermal energy comes from the Sun''s heat stored in the oceans."], "statements_hi": ["बायोगैस संयंत्र ऐसी गैस बनाता है जो मुख्यतः मीथेन होती है, और बचा हुआ घोल (slurry) अच्छी खाद बनता है।", "महासागरीय तापीय ऊर्जा का दोहन केवल वहीं हो सकता है जहाँ सतह का जल नीचे के जल से लगभग 20 °C या अधिक गर्म हो।", "भूतापीय ऊर्जा महासागरों में संचित सूर्य की ऊष्मा से आती है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. In a biogas plant, anaerobic micro-organisms decompose cow dung and other biomass to produce a gas with up to about 75 per cent methane, used for cooking and lighting; ocean thermal energy conversion plants use the difference in temperature between warm surface water and cold deep water, which must be 20 °C or more. Statement 3 is wrong: geothermal energy comes from the heat inside the Earth -- where molten rock pushed up from deep below heats underground water into ''hot spots'' and steam that can run turbines.','कथन 1 और 2 सही हैं। बायोगैस संयंत्र में अवायवीय सूक्ष्मजीव गोबर और अन्य जैवभार का अपघटन करके लगभग 75 प्रतिशत तक मीथेन वाली गैस बनाते हैं, जो खाना पकाने और रोशनी के काम आती है; महासागरीय तापीय ऊर्जा रूपांतरण संयंत्र गर्म सतही जल और ठंडे गहरे जल के तापमान के अंतर का उपयोग करते हैं, जो 20 °C या अधिक होना चाहिए। कथन 3 गलत है: भूतापीय ऊर्जा पृथ्वी के भीतर की ऊष्मा से आती है -- जहाँ गहराई से ऊपर धकेली गई पिघली चट्टानें भूमिगत जल को गर्म करके ''हॉट स्पॉट'' और भाप बनाती हैं, जो टरबाइन चला सकती है।','l1-env-biogas-otec-geothermal','original_pattern_matched','NCERT Class X, Science (Sources of Energy, earlier editions).','draft'),
('upsc','Environment & Ecology','Climate Science & Mitigation','statement_based','medium','Consider the following statements about nuclear power:','नाभिकीय (परमाणु) ऊर्जा के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["In a nuclear power plant, the heat released by the fission of heavy atoms such as uranium is used to produce steam that drives turbines.", "Nuclear power plants emit large amounts of carbon dioxide while generating electricity.", "The radioactive waste from nuclear plants becomes harmless within a few days."], "statements_hi": ["नाभिकीय बिजलीघर में यूरेनियम जैसे भारी परमाणुओं के विखंडन से निकली ऊष्मा से भाप बनाई जाती है, जो टरबाइन चलाती है।", "नाभिकीय बिजलीघर बिजली बनाते समय बड़ी मात्रा में कार्बन डाइऑक्साइड छोड़ते हैं।", "नाभिकीय संयंत्रों का रेडियोधर्मी कचरा कुछ ही दिनों में हानिरहित हो जाता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: a chain reaction of fission releases a great deal of heat, which is used as in a thermal plant to make steam and generate electricity. Statement 2 is wrong: fission itself emits no carbon dioxide, which is why nuclear power is counted among low-carbon sources. Statement 3 is wrong: the major hazard of nuclear power is the storage and disposal of spent fuel, which stays radioactive for a very long time and must be kept away from people and the environment; the high cost of plants and the risk of accidents are the other concerns.','केवल कथन 1 सही है: विखंडन की शृंखला अभिक्रिया बहुत अधिक ऊष्मा छोड़ती है, जिसका उपयोग तापीय बिजलीघर की तरह भाप बनाने और बिजली उत्पादन में होता है। कथन 2 गलत है: विखंडन स्वयं कोई कार्बन डाइऑक्साइड नहीं छोड़ता, इसीलिए नाभिकीय ऊर्जा को कम-कार्बन स्रोतों में गिना जाता है। कथन 3 गलत है: नाभिकीय ऊर्जा का मुख्य ख़तरा प्रयुक्त ईंधन का भंडारण और निपटान है, जो बहुत लंबे समय तक रेडियोधर्मी रहता है और जिसे लोगों तथा पर्यावरण से दूर रखना पड़ता है; संयंत्रों की ऊँची लागत और दुर्घटना का जोखिम अन्य चिंताएँ हैं।','l1-env-nuclear-fission-waste','original_pattern_matched','NCERT Class X, Science (Sources of Energy, earlier editions).','draft'),
('upsc','Environment & Ecology','Climate Science & Mitigation','statement_based','medium','Consider the following statements about the carbon cycle:','कार्बन चक्र के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["About 71 per cent of the earth''s carbon is found dissolved in the oceans, which help regulate the amount of carbon dioxide in the atmosphere.", "Burning fossil fuels, deforestation and forest fires add carbon dioxide to the atmosphere.", "Volcanic activity also releases carbon dioxide into the atmosphere.", "Decomposers return the carbon in dead organic matter to the atmosphere as carbon dioxide."], "statements_hi": ["पृथ्वी का लगभग 71 प्रतिशत कार्बन महासागरों में घुला हुआ है, जो वायुमंडल में कार्बन डाइऑक्साइड की मात्रा नियंत्रित करने में मदद करते हैं।", "जीवाश्म ईंधन जलाना, वनों की कटाई और वनाग्नि वायुमंडल में कार्बन डाइऑक्साइड जोड़ते हैं।", "ज्वालामुखी गतिविधि भी वायुमंडल में कार्बन डाइऑक्साइड छोड़ती है।", "अपघटक मृत कार्बनिक पदार्थ के कार्बन को कार्बन डाइऑक्साइड के रूप में वायुमंडल में लौटाते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": false}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": true}]'::jsonb,2,0.66,'All four statements are correct. Carbon cycles between the atmosphere, oceans, living things and rocks: plants fix it through photosynthesis, it passes along food chains, and respiration, decomposition, burning and volcanic activity return it to the air. Human activities -- rapid deforestation and the massive burning of fossil fuels for energy and transport -- have significantly increased the rate at which carbon dioxide is released, faster than the oceans and forests can take it up.','चारों कथन सही हैं। कार्बन वायुमंडल, महासागरों, सजीवों और चट्टानों के बीच घूमता है: पौधे प्रकाश-संश्लेषण से उसे स्थिर करते हैं, वह खाद्य शृंखलाओं में आगे बढ़ता है, और श्वसन, अपघटन, दहन तथा ज्वालामुखी गतिविधि उसे वायु में लौटाते हैं। मानवीय गतिविधियों -- वनों की तेज़ कटाई और ऊर्जा तथा परिवहन के लिए जीवाश्म ईंधनों के भारी दहन -- ने कार्बन डाइऑक्साइड छोड़े जाने की दर को काफ़ी बढ़ा दिया है, इतना कि महासागर और वन उसे उतनी तेज़ी से सोख नहीं पाते।','l1-env-carbon-cycle-ocean-reservoir','original_pattern_matched','NCERT Class XII, Biology (Ecosystem, earlier editions).','draft'),
('upsc','Environment & Ecology','Climate Science & Mitigation','statement_based','medium','Consider the following statements about the ozone layer and ultraviolet radiation:','ओज़ोन परत और पराबैंगनी विकिरण के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The thickness of the ozone in a column of air is measured in Dobson units.", "UV-B radiation can damage DNA and cause skin cancer, and a high dose can inflame the cornea of the eye, causing snow-blindness.", "The ozone ''hole'' forms over the Arctic every northern summer."], "statements_hi": ["वायु के किसी स्तंभ में ओज़ोन की मोटाई डॉब्सन इकाइयों में मापी जाती है।", "UV-B विकिरण DNA को क्षति पहुँचा सकता है और त्वचा कैंसर पैदा कर सकता है, और अधिक मात्रा आँख के कॉर्निया में सूजन लाकर हिम-अंधता (snow-blindness) पैदा कर सकती है।", "ओज़ोन ''छिद्र'' हर उत्तरी ग्रीष्म ऋतु में आर्कटिक के ऊपर बनता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Ozone in the stratosphere absorbs UV-B, which has a shorter wavelength than visible light and is highly injurious; the cornea absorbs UV-B, and a high dose can cause snow-blindness or cataract, while in the skin it can cause ageing and cancers. Statement 3 is wrong: the large area of thinned ozone known as the ozone hole forms over Antarctica, mainly in the southern spring (September-October), when chlorine from CFCs, activated on icy clouds in the very cold polar stratosphere, destroys ozone rapidly.','कथन 1 और 2 सही हैं। समताप मंडल की ओज़ोन UV-B को सोखती है, जिसकी तरंगदैर्ध्य दृश्य प्रकाश से छोटी है और जो अत्यंत हानिकारक है; कॉर्निया UV-B सोखता है, और अधिक मात्रा हिम-अंधता या मोतियाबिंद पैदा कर सकती है, जबकि त्वचा में यह बुढ़ापा और कैंसर ला सकता है। कथन 3 गलत है: पतली ओज़ोन का बड़ा क्षेत्र, जिसे ओज़ोन छिद्र कहते हैं, अंटार्कटिका के ऊपर, मुख्यतः दक्षिणी वसंत (सितंबर-अक्टूबर) में बनता है, जब बहुत ठंडे ध्रुवीय समताप मंडल के बर्फ़ीले बादलों पर सक्रिय हुई CFC की क्लोरीन ओज़ोन को तेज़ी से नष्ट करती है।','l1-env-dobson-uvb-snow-blindness','original_pattern_matched','NCERT Class XII, Biology (Environmental Issues, earlier editions).','draft'),
('upsc','Environment & Ecology','Climate Science & Mitigation','statement_based','medium','Consider the following measures:','निम्नलिखित उपायों पर विचार कीजिए:','{"statements": ["Cutting down the use of fossil fuels", "Improving the efficiency of energy use", "Reducing deforestation and planting trees", "Slowing down the growth of the human population"], "statements_hi": ["जीवाश्म ईंधनों का उपयोग घटाना", "ऊर्जा उपयोग की दक्षता बढ़ाना", "वनों की कटाई घटाना और वृक्ष लगाना", "मानव जनसंख्या की वृद्धि को धीमा करना"], "closing": "How many of the above can help to slow down global warming?", "closing_hi": "उपर्युक्त में से कितने उपाय वैश्विक तापन को धीमा करने में मदद कर सकते हैं?", "fixed_option_order": true, "craft": "recall"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": false}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": true}]'::jsonb,2,0.66,'All four can help to slow down global warming: the first two cut emissions at the source, forests take up carbon dioxide, and a slower growth of population reduces the total demand for energy and land. Countries also work together internationally to reduce greenhouse gas emissions, since the gases mix through the whole atmosphere wherever they are released.','चारों वैश्विक तापन को धीमा करने में मदद कर सकते हैं: पहले दो उपाय स्रोत पर ही उत्सर्जन घटाते हैं, वन कार्बन डाइऑक्साइड सोखते हैं, और जनसंख्या की धीमी वृद्धि ऊर्जा और भूमि की कुल माँग घटाती है। देश ग्रीनहाउस गैसों का उत्सर्जन घटाने के लिए अंतरराष्ट्रीय स्तर पर भी मिलकर काम करते हैं, क्योंकि ये गैसें कहीं भी छोड़ी जाएँ, पूरे वायुमंडल में मिल जाती हैं।','l1-env-measures-slow-global-warming','original_pattern_matched','NCERT Class XII, Biology (Environmental Issues, earlier editions).','draft'),
('upsc','Environment & Ecology','Climate Science & Mitigation','assertion_reason','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "Global average temperatures fell slightly for a year or two after the eruption of Mount Pinatubo in the Philippines in 1991.", "assertion_hi": "1991 में फ़िलीपींस में माउंट पिनाटूबो के विस्फोट के बाद एक-दो वर्ष तक वैश्विक औसत तापमान कुछ घट गया।", "reason": "The eruption threw large amounts of aerosols into the upper atmosphere, which reflected part of the incoming sunlight back to space.", "reason_hi": "विस्फोट ने ऊपरी वायुमंडल में बड़ी मात्रा में ऐरोसोल फेंके, जिन्होंने आने वाली धूप का एक भाग वापस अंतरिक्ष में परावर्तित कर दिया।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true, "craft": "inference"}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": true}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct, and Statement-II explains Statement-I. Volcanism is one of the natural causes of climate change: large eruptions put aerosols, mainly sulphate droplets, high into the atmosphere, where they stay for a considerable time and reduce the solar radiation reaching the surface. The cooling is temporary, lasting only as long as the aerosols remain aloft -- unlike the long-term warming caused by greenhouse gases.','दोनों कथन सही हैं, और कथन-II कथन-I की व्याख्या करता है। ज्वालामुखी जलवायु परिवर्तन के प्राकृतिक कारणों में से एक है: बड़े विस्फोट ऐरोसोल, मुख्यतः सल्फ़ेट की बूँदें, वायुमंडल में ऊँचाई तक पहुँचाते हैं, जहाँ वे काफ़ी समय रहकर सतह तक पहुँचने वाले सौर विकिरण को घटाते हैं। यह शीतलन अस्थायी होता है और तभी तक रहता है जब तक ऐरोसोल ऊपर रहें -- ग्रीनहाउस गैसों से होने वाले दीर्घकालिक तापन के विपरीत।','l1-env-pinatubo-aerosol-cooling','original_pattern_matched','NCERT Class XI, Geography -- Fundamentals of Physical Geography (World Climate and Climate Change).','draft'),
('upsc','Environment & Ecology','Climate Science & Mitigation','statement_based','hard','Consider the following statements about the causes of climate change:','जलवायु परिवर्तन के कारणों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Some meteorologists link an increase in the number of sunspots with cooler, wetter weather and greater storminess.", "These links, however, have not been shown to be statistically significant.", "How strongly a greenhouse gas warms the earth depends on how much its concentration rises, how long it stays in the atmosphere and the wavelengths of radiation it absorbs."], "statements_hi": ["कुछ मौसम विज्ञानी सौर कलंकों (sunspots) की संख्या बढ़ने को ठंडे, अधिक नम मौसम और अधिक तूफ़ानों से जोड़ते हैं।", "पर ये संबंध सांख्यिकीय रूप से महत्वपूर्ण सिद्ध नहीं हुए हैं।", "कोई ग्रीनहाउस गैस पृथ्वी को कितना गर्म करती है, यह इस पर निर्भर है कि उसकी सांद्रता कितनी बढ़ी, वह वायुमंडल में कितने समय रहती है, और वह किन तरंगदैर्ध्यों का विकिरण सोखती है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. Among the astronomical causes of climate change, changes in solar output associated with sunspot activity have been proposed -- more sunspots with cooler, wetter, stormier weather, fewer with warmer, drier conditions -- but the evidence is weak. The anthropogenic cause, the rising concentration of greenhouse gases, works through these three factors; CFCs, for instance, are present in tiny amounts but are long-lived and absorb strongly in a part of the spectrum where little else does, so they are highly effective.','तीनों कथन सही हैं। जलवायु परिवर्तन के खगोलीय कारणों में सौर कलंक गतिविधि से जुड़े सौर उत्पादन के परिवर्तन सुझाए गए हैं -- अधिक सौर कलंकों के साथ ठंडा, नम, तूफ़ानी मौसम, और कम के साथ गर्म, शुष्क दशाएँ -- पर साक्ष्य कमज़ोर हैं। मानवजनित कारण, ग्रीनहाउस गैसों की बढ़ती सांद्रता, इन तीन कारकों के माध्यम से काम करता है; उदाहरण के लिए CFC बहुत थोड़ी मात्रा में हैं, पर दीर्घजीवी हैं और स्पेक्ट्रम के उस भाग में प्रबलता से अवशोषण करते हैं जहाँ और कुछ नहीं करता, इसलिए वे अत्यधिक प्रभावी हैं।','l1-env-sunspots-ghg-effectiveness','original_pattern_matched','NCERT Class XI, Geography -- Fundamentals of Physical Geography (World Climate and Climate Change).','draft'),
('upsc','Environment & Ecology','Climate Agreements & Carbon Markets','mcq','easy','In carbon markets, one carbon credit generally represents','कार्बन बाज़ारों में एक कार्बन क्रेडिट सामान्यतः किसका प्रतिनिधित्व करता है?','{"craft": "precision"}'::jsonb,'[{"id": "a", "body": "one kilogram of carbon dioxide saved by a household through energy-efficient lighting", "body_hi": "ऊर्जा-दक्ष प्रकाश से किसी घर द्वारा बचाई गई एक किलोग्राम कार्बन डाइऑक्साइड", "isCorrect": false}, {"id": "b", "body": "one tonne of carbon dioxide, or its equivalent, reduced or removed", "body_hi": "एक टन कार्बन डाइऑक्साइड, या उसके समतुल्य, की कमी या निष्कासन", "isCorrect": true}, {"id": "c", "body": "one hectare of new forest planted under a government scheme", "body_hi": "किसी सरकारी योजना के तहत लगाया गया एक हेक्टेयर नया वन", "isCorrect": false}, {"id": "d", "body": "one megawatt of renewable power capacity installed", "body_hi": "स्थापित की गई एक मेगावाट नवीकरणीय बिजली क्षमता", "isCorrect": false}]'::jsonb,2,0.66,'A carbon credit stands for one tonne of carbon dioxide equivalent (tCO2e) that has been reduced, avoided or removed from the atmosphere; other greenhouse gases are converted into this common unit using their global warming potentials. A buyer can use credits to offset its own emissions, so the market works only if each tonne is real, measurable and counted once.','एक कार्बन क्रेडिट एक टन कार्बन डाइऑक्साइड समतुल्य (tCO2e) का प्रतिनिधित्व करता है जिसे घटाया, टाला या वायुमंडल से हटाया गया हो; अन्य ग्रीनहाउस गैसों को उनकी वैश्विक तापन क्षमता के आधार पर इसी साझा इकाई में बदला जाता है। ख़रीदार क्रेडिट से अपने उत्सर्जन की भरपाई (offset) कर सकता है, इसलिए बाज़ार तभी काम करता है जब हर टन वास्तविक, मापने योग्य और केवल एक बार गिना गया हो।','l1-env-carbon-credit-one-tonne','original_pattern_matched','United Nations Framework Convention on Climate Change; Bureau of Energy Efficiency.','draft'),
('upsc','Environment & Ecology','Climate Agreements & Carbon Markets','statement_based','easy','Consider the following statements about India''s climate plans:','भारत की जलवायु योजनाओं के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["India''s National Action Plan on Climate Change, released in 2008, set out eight national missions.", "States cannot prepare climate plans of their own, and must follow the national plan."], "statements_hi": ["2008 में जारी भारत की राष्ट्रीय जलवायु परिवर्तन कार्य योजना ने आठ राष्ट्रीय मिशन निर्धारित किए।", "राज्य अपनी जलवायु योजनाएँ नहीं बना सकते, और उन्हें राष्ट्रीय योजना का ही पालन करना होता है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: the National Action Plan on Climate Change, released by the Prime Minister''s Council on Climate Change in 2008, set out eight missions covering solar energy, energy efficiency, sustainable habitat, water, the Himalayan ecosystem, a green India, sustainable agriculture and strategic knowledge. Statement 2 is wrong: the States and Union Territories have prepared State Action Plans on Climate Change, consistent with the national plan but suited to their own conditions and priorities.','केवल कथन 1 सही है: जलवायु परिवर्तन पर प्रधानमंत्री की परिषद द्वारा 2008 में जारी राष्ट्रीय कार्य योजना ने सौर ऊर्जा, ऊर्जा दक्षता, सतत आवास, जल, हिमालयी पारितंत्र, हरित भारत, सतत कृषि और रणनीतिक ज्ञान से जुड़े आठ मिशन निर्धारित किए। कथन 2 गलत है: राज्यों और केंद्रशासित प्रदेशों ने जलवायु परिवर्तन पर राज्य कार्य योजनाएँ तैयार की हैं, जो राष्ट्रीय योजना के अनुरूप हैं पर उनकी अपनी परिस्थितियों और प्राथमिकताओं के अनुकूल हैं।','l1-env-napcc-2008-state-plans','original_pattern_matched','Ministry of Environment, Forest and Climate Change, National Action Plan on Climate Change (2008).','draft'),
('upsc','Environment & Ecology','Climate Agreements & Carbon Markets','statement_based','easy','Consider the following statements about Mission LiFE:','मिशन LiFE के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Mission LiFE (Lifestyle for Environment) encourages individuals and communities to adopt sustainable habits in daily life, such as saving energy and water and cutting waste.", "India first put forward the idea at COP26 in Glasgow in 2021."], "statements_hi": ["मिशन LiFE (पर्यावरण के लिए जीवनशैली) व्यक्तियों और समुदायों को दैनिक जीवन में ऊर्जा और जल बचाने तथा कचरा घटाने जैसी सतत आदतें अपनाने के लिए प्रेरित करता है।", "भारत ने यह विचार पहली बार 2021 में ग्लासगो में COP26 में रखा।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "recall"}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct. The idea of LiFE -- ''mindful and deliberate utilisation'' instead of ''mindless and destructive consumption'' -- was put forward by India at COP26 and launched as a mission in October 2022 at Ekta Nagar (Kevadia), Gujarat, in the presence of the UN Secretary-General. It rests on the view that individual and community choices, multiplied across billions of people, can make a large difference alongside government and industry action.','दोनों कथन सही हैं। LiFE का विचार -- ''विवेकहीन और विनाशकारी उपभोग'' के स्थान पर ''सजग और सोचा-समझा उपयोग'' -- भारत ने COP26 में रखा और अक्टूबर 2022 में गुजरात के एकता नगर (केवड़िया) में संयुक्त राष्ट्र महासचिव की उपस्थिति में इसे मिशन के रूप में शुरू किया गया। यह इस दृष्टि पर टिका है कि अरबों लोगों में गुणित होकर व्यक्तिगत और सामुदायिक चुनाव सरकार और उद्योग के प्रयासों के साथ बड़ा अंतर ला सकते हैं।','l1-env-mission-life-cop26','original_pattern_matched','Ministry of Environment, Forest and Climate Change, Mission LiFE.','draft'),
('upsc','Environment & Ecology','Climate Agreements & Carbon Markets','mcq','medium','The Energy Conservation Building Code, which sets minimum energy-performance standards for large new commercial buildings, was developed by','बड़ी नई वाणिज्यिक इमारतों के लिए न्यूनतम ऊर्जा-प्रदर्शन मानक तय करने वाली ऊर्जा संरक्षण भवन संहिता किसने विकसित की?','{"craft": "precision"}'::jsonb,'[{"id": "a", "body": "the Central Pollution Control Board", "body_hi": "केंद्रीय प्रदूषण नियंत्रण बोर्ड", "isCorrect": false}, {"id": "b", "body": "the Bureau of Indian Standards", "body_hi": "भारतीय मानक ब्यूरो", "isCorrect": false}, {"id": "c", "body": "the Ministry of New and Renewable Energy", "body_hi": "नवीन और नवीकरणीय ऊर्जा मंत्रालय", "isCorrect": false}, {"id": "d", "body": "the Bureau of Energy Efficiency", "body_hi": "ऊर्जा दक्षता ब्यूरो (BEE)", "isCorrect": true}]'::jsonb,2,0.66,'The Bureau of Energy Efficiency, set up under the Energy Conservation Act, 2001, developed the Energy Conservation Building Code (first issued in 2007 and revised in 2017), which States adopt and enforce; it covers the building envelope, lighting, air-conditioning and electrical systems. BEE also runs the star-labelling programme for appliances such as air-conditioners and refrigerators, and a code for residential buildings, the Eco-Niwas Samhita.','ऊर्जा संरक्षण अधिनियम, 2001 के तहत स्थापित ऊर्जा दक्षता ब्यूरो ने ऊर्जा संरक्षण भवन संहिता (पहली बार 2007 में जारी, 2017 में संशोधित) विकसित की, जिसे राज्य अपनाते और लागू करते हैं; इसमें इमारत का बाहरी आवरण, प्रकाश, वातानुकूलन और विद्युत प्रणालियाँ शामिल हैं। BEE एयर-कंडीशनर और रेफ़्रिजरेटर जैसे उपकरणों के लिए स्टार-लेबलिंग कार्यक्रम और आवासीय इमारतों के लिए इको-निवास संहिता भी चलाता है।','l1-env-ecbc-bee','original_pattern_matched','Bureau of Energy Efficiency; Energy Conservation Act, 2001.','draft'),
('upsc','Environment & Ecology','Climate Agreements & Carbon Markets','statement_based','medium','Consider the following statements about REDD+ under the UN climate convention:','संयुक्त राष्ट्र जलवायु अभिसमय के तहत REDD+ के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["REDD+ rewards developing countries for reducing emissions from deforestation and forest degradation.", "The ''+'' adds the conservation and sustainable management of forests and the enhancement of forest carbon stocks.", "REDD+ applies to the forests of developed countries, which hold the largest forest carbon stocks."], "statements_hi": ["REDD+ विकासशील देशों को वनों की कटाई और वन-क्षरण से होने वाले उत्सर्जन घटाने के लिए पुरस्कृत करता है।", "''+'' में वनों का संरक्षण और सतत प्रबंधन तथा वन कार्बन भंडार की वृद्धि जोड़े गए हैं।", "REDD+ विकसित देशों के वनों पर लागू होता है, जिनके पास सबसे बड़े वन कार्बन भंडार हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Since deforestation and forest degradation are a large source of emissions, REDD+ offers developing countries results-based payments for measured, reported and verified reductions, provided safeguards for the rights of indigenous peoples and local communities are respected. Statement 3 is wrong: REDD+ is designed for developing countries, where most tropical deforestation takes place; it is recognised in Article 5 of the Paris Agreement.','कथन 1 और 2 सही हैं। चूँकि वनों की कटाई और वन-क्षरण उत्सर्जन का बड़ा स्रोत हैं, इसलिए REDD+ विकासशील देशों को मापी गई, रिपोर्ट की गई और सत्यापित कमी के लिए परिणाम-आधारित भुगतान देता है, बशर्ते मूलनिवासियों और स्थानीय समुदायों के अधिकारों की सुरक्षा का सम्मान हो। कथन 3 गलत है: REDD+ विकासशील देशों के लिए बनाया गया है, जहाँ अधिकांश उष्णकटिबंधीय वन-कटाई होती है; पेरिस समझौते के अनुच्छेद 5 में इसे मान्यता दी गई है।','l1-env-redd-plus-developing-countries','original_pattern_matched','United Nations Framework Convention on Climate Change (REDD+); Paris Agreement, Article 5.','draft'),
('upsc','Environment & Ecology','Climate Agreements & Carbon Markets','statement_based','medium','Consider the following statements about the carbon footprint:','कार्बन फ़ुटप्रिंट के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["A carbon footprint is the total greenhouse gas emissions caused directly and indirectly by a person, product or organisation, expressed as carbon dioxide equivalent.", "Food has no carbon footprint, since crops absorb carbon dioxide as they grow.", "A product''s carbon footprint counts only the emissions from its final use, not from its manufacture or transport."], "statements_hi": ["कार्बन फ़ुटप्रिंट किसी व्यक्ति, उत्पाद या संगठन द्वारा प्रत्यक्ष और अप्रत्यक्ष रूप से होने वाला कुल ग्रीनहाउस गैस उत्सर्जन है, जिसे कार्बन डाइऑक्साइड समतुल्य में व्यक्त किया जाता है।", "भोजन का कोई कार्बन फ़ुटप्रिंट नहीं होता, क्योंकि फ़सलें बढ़ते समय कार्बन डाइऑक्साइड सोखती हैं।", "किसी उत्पाद के कार्बन फ़ुटप्रिंट में केवल उसके अंतिम उपयोग का उत्सर्जन गिना जाता है, उसके निर्माण या परिवहन का नहीं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "application"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. Statement 2 is wrong: producing food involves fertilisers, irrigation pumps, machinery, transport and storage, and flooded paddy fields and livestock release methane, so food carries a substantial footprint even though crops take up carbon as they grow. Statement 3 is wrong: a footprint is measured over the whole life cycle -- extracting raw materials, manufacture, transport, use and disposal -- which is why a product that uses little energy in use may still have a large footprint.','केवल कथन 1 सही है। कथन 2 गलत है: भोजन के उत्पादन में उर्वरक, सिंचाई पंप, मशीनें, परिवहन और भंडारण लगते हैं, और जलमग्न धान के खेत तथा पशुधन मीथेन छोड़ते हैं, इसलिए फ़सलों के कार्बन सोखने के बावजूद भोजन का फ़ुटप्रिंट काफ़ी होता है। कथन 3 गलत है: फ़ुटप्रिंट पूरे जीवन-चक्र पर मापा जाता है -- कच्चा माल निकालना, निर्माण, परिवहन, उपयोग और निपटान -- इसीलिए उपयोग में कम ऊर्जा लेने वाले उत्पाद का फ़ुटप्रिंट भी बड़ा हो सकता है।','l1-env-carbon-footprint-life-cycle','original_pattern_matched','United Nations Environment Programme; Bureau of Energy Efficiency.','draft'),
('upsc','Environment & Ecology','Climate Agreements & Carbon Markets','statement_based','medium','Consider the following statements about India''s Long-Term Low Emission Development Strategy:','भारत की दीर्घकालिक निम्न उत्सर्जन विकास रणनीति (LT-LEDS) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["India submitted it to the UN climate convention at COP27 in 2022.", "It describes how India''s development can shift towards low emissions across sectors such as electricity, transport, urban development and industry.", "It commits India to stop using coal by 2030."], "statements_hi": ["भारत ने इसे 2022 में COP27 में संयुक्त राष्ट्र जलवायु अभिसमय को सौंपा।", "यह बताती है कि बिजली, परिवहन, शहरी विकास और उद्योग जैसे क्षेत्रों में भारत का विकास निम्न उत्सर्जन की ओर कैसे बढ़ सकता है।", "यह भारत को 2030 तक कोयले का उपयोग बंद करने के लिए प्रतिबद्ध करती है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Under the Paris Agreement, countries are invited to communicate long-term strategies alongside their shorter-term nationally determined contributions; India''s strategy, submitted at Sharm el-Sheikh, sets out transitions in electricity, transport, cities, industry and forests, with an emphasis on climate justice and India''s development needs. Statement 3 is wrong: it sets no date for ending coal use; it envisages a gradual, just transition in which coal continues to meet part of the country''s energy needs for some time.','कथन 1 और 2 सही हैं। पेरिस समझौते के तहत देशों से अपेक्षा है कि वे अपने अल्पकालिक राष्ट्रीय स्तर पर निर्धारित योगदानों के साथ दीर्घकालिक रणनीतियाँ भी बताएँ; शर्म अल-शेख़ में सौंपी गई भारत की रणनीति बिजली, परिवहन, शहरों, उद्योग और वनों में बदलाव की रूपरेखा देती है, जिसमें जलवायु न्याय और भारत की विकास आवश्यकताओं पर ज़ोर है। कथन 3 गलत है: यह कोयले का उपयोग समाप्त करने की कोई तिथि तय नहीं करती; यह एक क्रमिक, न्यायसंगत परिवर्तन की परिकल्पना करती है जिसमें कोयला कुछ समय तक देश की ऊर्जा ज़रूरतों का एक भाग पूरा करता रहेगा।','l1-env-india-lt-leds-cop27','original_pattern_matched','Ministry of Environment, Forest and Climate Change, India''s Long-Term Low-Carbon Development Strategy (2022); UNFCCC.','draft'),
('upsc','Environment & Ecology','Climate Agreements & Carbon Markets','statement_based','medium','Consider the following statements about the quality of carbon offsets:','कार्बन ऑफ़सेट की गुणवत्ता के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["An offset project is ''additional'' only if the emission reduction would not have happened without the money from selling the credits.", "Permanence matters, since carbon stored in a forest can return to the air if the forest later burns or is cut.", "Counting the same reduction towards the targets of two different buyers, known as double counting, undermines a carbon market."], "statements_hi": ["कोई ऑफ़सेट परियोजना तभी ''अतिरिक्त'' (additional) है जब क्रेडिट बेचकर मिलने वाले धन के बिना उत्सर्जन में वह कमी न होती।", "स्थायित्व मायने रखता है, क्योंकि वन में संचित कार्बन बाद में वन जलने या कटने पर वायु में लौट सकता है।", "एक ही कमी को दो अलग-अलग ख़रीदारों के लक्ष्यों में गिनना, जिसे दोहरी गणना कहते हैं, कार्बन बाज़ार को कमज़ोर करता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "inference"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. A credit is meant to stand for one real tonne of emissions avoided or removed, so the reduction must be additional (caused by the project), permanent (not reversed later) and counted only once; otherwise a buyer who offsets its emissions has not actually balanced them. Rules under Article 6 of the Paris Agreement, such as ''corresponding adjustments'' between countries, are designed to prevent double counting.','तीनों कथन सही हैं। एक क्रेडिट का अर्थ है उत्सर्जन का एक वास्तविक टन, जिसे टाला या हटाया गया हो, इसलिए कमी अतिरिक्त (परियोजना के कारण हुई), स्थायी (बाद में उलटी न हो) और केवल एक बार गिनी गई होनी चाहिए; अन्यथा अपने उत्सर्जन की भरपाई करने वाले ख़रीदार ने वास्तव में उसे संतुलित नहीं किया। पेरिस समझौते के अनुच्छेद 6 के नियम, जैसे देशों के बीच ''संगत समायोजन'' (corresponding adjustments), दोहरी गणना रोकने के लिए बनाए गए हैं।','l1-env-offset-additionality-permanence','original_pattern_matched','United Nations Framework Convention on Climate Change (Paris Agreement, Article 6).','draft'),
('upsc','Environment & Ecology','Climate Agreements & Carbon Markets','assertion_reason','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "Under the Perform, Achieve and Trade scheme, an energy-intensive industrial unit that saves more energy than its target can earn money from the extra saving.", "assertion_hi": "निष्पादन, उपलब्धि और व्यापार (PAT) योजना के तहत ऊर्जा-गहन औद्योगिक इकाई अपने लक्ष्य से अधिक ऊर्जा बचाकर उस अतिरिक्त बचत से धन कमा सकती है।", "reason": "Such a unit receives Energy Saving Certificates, which it can sell to units that fall short of their targets.", "reason_hi": "ऐसी इकाई को ऊर्जा बचत प्रमाणपत्र (ESCert) मिलते हैं, जिन्हें वह अपने लक्ष्य से चूकने वाली इकाइयों को बेच सकती है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true, "craft": "linkage"}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": true}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct, and Statement-II explains Statement-I. Under PAT, run by the Bureau of Energy Efficiency under the National Mission for Enhanced Energy Efficiency since 2012, ''designated consumers'' in sectors such as steel, cement, aluminium and thermal power are given targets to cut their specific energy consumption; units that overachieve earn tradable Energy Saving Certificates, and those that fall short must buy them or pay a penalty -- a market-based way of rewarding efficiency.','दोनों कथन सही हैं, और कथन-II कथन-I की व्याख्या करता है। राष्ट्रीय संवर्धित ऊर्जा दक्षता मिशन के तहत 2012 से ऊर्जा दक्षता ब्यूरो द्वारा चलाई जा रही PAT में इस्पात, सीमेंट, एल्युमिनियम और ताप बिजली जैसे क्षेत्रों के ''नामित उपभोक्ताओं'' को अपनी विशिष्ट ऊर्जा खपत घटाने के लक्ष्य दिए जाते हैं; लक्ष्य से आगे निकलने वाली इकाइयाँ व्यापार योग्य ऊर्जा बचत प्रमाणपत्र पाती हैं, और पिछड़ने वालों को उन्हें ख़रीदना या दंड देना पड़ता है -- दक्षता को पुरस्कृत करने का बाज़ार-आधारित तरीक़ा।','l1-env-pat-escerts','original_pattern_matched','Bureau of Energy Efficiency (Perform, Achieve and Trade scheme); Energy Conservation Act, 2001.','draft'),
('upsc','Environment & Ecology','Climate Agreements & Carbon Markets','statement_based','hard','Consider the following statements about the Kyoto Protocol:','क्योटो प्रोटोकॉल के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Its first commitment period ran from 2008 to 2012.", "The Doha Amendment set a second commitment period, from 2013 to 2020.", "The United States signed the Protocol but never ratified it.", "Canada withdrew from the Protocol in 2011."], "statements_hi": ["इसकी पहली प्रतिबद्धता अवधि 2008 से 2012 तक थी।", "दोहा संशोधन ने 2013 से 2020 तक दूसरी प्रतिबद्धता अवधि तय की।", "संयुक्त राज्य अमेरिका ने प्रोटोकॉल पर हस्ताक्षर किए, पर कभी उसका अनुसमर्थन नहीं किया।", "कनाडा 2011 में प्रोटोकॉल से हट गया।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "recall"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": false}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": true}]'::jsonb,2,0.66,'All four statements are correct. The binding targets for industrialised countries applied over the first commitment period, 2008-2012; the Doha Amendment, adopted in 2012, created a second period to 2020, though it entered into force only on the last day of 2020. The absence of the United States and the later withdrawal of Canada, together with the lack of obligations for fast-growing developing economies, weakened the Protocol -- one reason the Paris Agreement replaced its top-down targets with nationally determined contributions from all countries.','चारों कथन सही हैं। औद्योगिक देशों के बाध्यकारी लक्ष्य पहली प्रतिबद्धता अवधि, 2008-2012, पर लागू थे; 2012 में अपनाए गए दोहा संशोधन ने 2020 तक दूसरी अवधि बनाई, यद्यपि वह 2020 के अंतिम दिन ही लागू हो पाया। संयुक्त राज्य अमेरिका की अनुपस्थिति और बाद में कनाडा के हटने, साथ ही तेज़ी से बढ़ती विकासशील अर्थव्यवस्थाओं के लिए दायित्वों के अभाव, ने प्रोटोकॉल को कमज़ोर किया -- यह एक कारण है कि पेरिस समझौते ने उसके ऊपर से तय लक्ष्यों के स्थान पर सभी देशों के राष्ट्रीय स्तर पर निर्धारित योगदान रखे।','l1-env-kyoto-commitment-periods','original_pattern_matched','United Nations Framework Convention on Climate Change (Kyoto Protocol; Doha Amendment).','draft'),
('upsc','Environment & Ecology','Climate Agreements & Carbon Markets','match_the_following','hard','Consider the following pairs of missions under India''s National Action Plan on Climate Change and their focus:','भारत की राष्ट्रीय जलवायु परिवर्तन कार्य योजना के मिशनों और उनके केंद्र-बिंदु के निम्नलिखित युग्मों पर विचार कीजिए:','{"list_1": ["1. National Solar Mission", "2. National Mission for Enhanced Energy Efficiency", "3. National Mission for Sustaining the Himalayan Ecosystem", "4. National Mission for a Green India"], "list_1_hi": ["1. राष्ट्रीय सौर मिशन", "2. राष्ट्रीय संवर्धित ऊर्जा दक्षता मिशन", "3. हिमालयी पारितंत्र को बनाए रखने का राष्ट्रीय मिशन", "4. हरित भारत राष्ट्रीय मिशन"], "list_2": ["Promoting the use of solar energy for power and other uses", "Includes the Perform, Achieve and Trade scheme", "Safeguarding Himalayan glaciers and mountain ecosystems", "Expanding nuclear power to replace coal"], "list_2_hi": ["बिजली और अन्य उपयोगों के लिए सौर ऊर्जा को बढ़ावा देना", "इसमें निष्पादन, उपलब्धि और व्यापार (PAT) योजना शामिल है", "हिमालयी हिमनदों और पर्वतीय पारितंत्रों की रक्षा", "कोयले के स्थान पर नाभिकीय ऊर्जा का विस्तार"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": true}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": false}]'::jsonb,2,0.66,'Pairs 1, 2 and 3 are correctly matched. Pair 4 is wrong: the Green India Mission aims to protect, restore and enhance India''s forest cover -- increasing forest and tree cover and improving the quality of degraded forests -- and to respond to climate change through both adaptation and mitigation; it has nothing to do with nuclear power. The other missions of the plan deal with sustainable habitat, water, sustainable agriculture and strategic knowledge for climate change.','युग्म 1, 2 और 3 सही सुमेलित हैं। युग्म 4 गलत है: हरित भारत मिशन का उद्देश्य भारत के वन आवरण की रक्षा, पुनर्स्थापना और वृद्धि करना -- वन और वृक्ष आवरण बढ़ाना और क्षरित वनों की गुणवत्ता सुधारना -- तथा अनुकूलन और शमन, दोनों से जलवायु परिवर्तन का सामना करना है; इसका नाभिकीय ऊर्जा से कोई संबंध नहीं। योजना के अन्य मिशन सतत आवास, जल, सतत कृषि और जलवायु परिवर्तन के लिए रणनीतिक ज्ञान से संबंधित हैं।','l1-env-napcc-missions-pairs','original_pattern_matched','Ministry of Environment, Forest and Climate Change, National Action Plan on Climate Change (2008).','draft')
